import React, { useState } from 'react';

const Contact = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Message envoyé :', formData);
    alert('Merci pour votre message !');
    setFormData({ name: '', email: '', message: '' });
  };

  const contactInfo = [
    {
      title: "Email direct",
      content: "contact@entreprise.com",
      color: "from-blue-500 to-blue-600"
    },
    {
      title: "Téléphone",
      content: "+33 1 23 45 67 89",
      color: "from-emerald-500 to-emerald-600"
    },
    {
      title: "Adresse",
      content: "123 Rue de Paris, 75001",
      color: "from-purple-500 to-purple-600"
    }
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-white to-blue-50 py-20 px-4">
      <div className="max-w-6xl mx-auto">

        {/* Titre */}
        <div className="text-center mb-16">
          <h1 className="text-5xl md:text-6xl font-bold text-gray-800 mb-4">
            Contactez <span className="text-blue-600">nous</span>
          </h1>
          <p className="text-xl text-gray-600 max-w-2xl mx-auto">
            Nous sommes disponibles pour discuter de votre projet à tout moment.
          </p>
        </div>

        <div className="grid lg:grid-cols-2 gap-12">

          {/* Info Cards */}
          <div className="space-y-8">
            {contactInfo.map((item, index) => (
              <div 
                key={index}
                className="bg-white rounded-2xl p-8 shadow-lg hover:shadow-2xl transition-all duration-500"
              >
                <div className={`bg-gradient-to-r ${item.color} w-3 h-12 rounded-full mb-4`} />
                <h3 className="text-2xl font-bold text-gray-800 mb-2">{item.title}</h3>
                <p className="text-gray-600 text-lg">{item.content}</p>
              </div>
            ))}
          </div>

          {/* Formulaire */}
          <div className="bg-white rounded-2xl shadow-2xl p-10">
            <form onSubmit={handleSubmit} className="space-y-8">
              <input
                type="text"
                placeholder="Votre nom"
                className="w-full px-6 py-4 text-lg border-b-2 border-gray-200 focus:border-blue-500 outline-none"
                value={formData.name}
                onChange={(e) =>
                  setFormData({ ...formData, name: e.target.value })
                }
              />

              <input
                type="email"
                placeholder="Votre email"
                className="w-full px-6 py-4 text-lg border-b-2 border-gray-200 focus:border-blue-500 outline-none"
                value={formData.email}
                onChange={(e) =>
                  setFormData({ ...formData, email: e.target.value })
                }
              />

              <textarea
                placeholder="Votre message..."
                rows="5"
                className="w-full px-6 py-4 text-lg border-b-2 border-gray-200 focus:border-blue-500 outline-none resize-none"
                value={formData.message}
                onChange={(e) =>
                  setFormData({ ...formData, message: e.target.value })
                }
              />

              <button
                type="submit"
                className="w-full bg-gradient-to-r from-blue-600 to-purple-600 text-white text-lg font-medium py-5 rounded-xl hover:shadow-xl transition-transform hover:-translate-y-1"
              >
                Envoyer →
              </button>
            </form>
          </div>
        </div>

        {/* CTA */}
        <div className="mt-20 text-center">
          <div className="inline-block bg-gradient-to-r from-blue-500 to-purple-500 text-white px-8 py-4 rounded-full text-lg font-medium shadow-xl">
            📞 Appelez-nous : +33 6 12 34 56 78
          </div>
        </div>

      </div>
    </div>
  );
};

export default Contact;
